def next_lesson(lessons, completed):
    for lesson in lessons:
        if not lesson:
            continue
        if lesson not in completed:
            return f'Next lesson: {lesson}'
    else:
        return 'All lessons complete'

print(next_lesson(['', 'variables', 'functions'], {'variables'}))
